INSERT INTO categories (id, name, status, checked, description, sort_order) VALUES ('efectivo', 'Efectivo Marin', 'confirmado', 1, 'Pagos en efectivo registrados aparte, 2025 (hoja SUELDOS PAGADOS).', 2);
