INSERT INTO categories (id, name, status, checked, description, sort_order) VALUES ('pagos', 'Luz / agua / otros pagos / transf. Santander', 'confirmado', 1, 'Tabla PAGOS de la hoja SUELDOS ANTERIORES, 2024-2025. Se asume que estas cuentas se pagaron a nombre de Rossy como parte de su sueldo.', 4);
