INSERT INTO categories (id, name, status, checked, description, sort_order) VALUES ('isabel', 'Transferencia "isabel" (01-oct-2024)', 'excluido', 0, 'Misma tabla anterior, pero esta fila esta anotada con el nombre "isabel" -- probablemente no es un pago a Rossy.', 6);
INSERT INTO categories (id, name, status, checked, description, sort_order) VALUES ('clientes', 'Transferencias clientes 2023-2024', 'excluido', 0, 'Columna TRANSFERENCIAS CLIENTES -- parecen ingresos del negocio (ventas), no pagos a Rossy.', 7);
INSERT INTO categories (id, name, status, checked, description, sort_order) VALUES ('celular', 'Plan de celular en efectivo 2025', 'excluido', 0, 'Pagos de plan de celular -- parece un gasto del negocio, no sueldo.', 8);
INSERT INTO categories (id, name, status, checked, description, sort_order) VALUES ('colA', 'Cifras sueltas sin encabezado (2025)', 'excluido', 0, 'Numeros en la columna A junto a la tabla de pagos, sin encabezado ni descripcion. Origen incierto.', 9);
